#!/usr/bin/env node
// tokens.json → theme.css (shadcn vars for panel + cards) and ../../themes/shadcn_ui.yaml (HA theme).
// `--check` fails if generated files are out of date (used in CI).
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const t = JSON.parse(readFileSync(resolve(here, "tokens.json"), "utf8"));
const check = process.argv.includes("--check");

const vars = (o) => Object.entries(o).map(([k, v]) => `  --${k}: ${v};`).join("\n");

const css = `/* GENERATED by packages/tokens/build.mjs from tokens.json — do not edit by hand. */
:root, :host {
  --radius: ${t.radius};
  --font-sans: ${t.font};
${vars(t.light)}
}

.dark, :host([dark]) {
${vars(t.dark)}
}
`;

// Home Assistant theme: maps the same tokens onto HA's theme variables so stock screens
// (settings, more-info, the eveus/deye views until they are redone) match the new UI.
const radiusPx = `${Math.round(parseFloat(t.radius) * 16)}px`;
const ha = (p) => ({
  "primary-color": p.primary,
  "accent-color": p.info,
  "primary-background-color": p.background,
  "secondary-background-color": p.muted,
  "card-background-color": p.card,
  "ha-card-background": p.card,
  "ha-card-border-color": p.border,
  "ha-card-border-width": "1px",
  "ha-card-border-radius": radiusPx,
  "ha-card-box-shadow": "none",
  "primary-text-color": p.foreground,
  "secondary-text-color": p["muted-foreground"],
  "disabled-text-color": p["muted-foreground"],
  "divider-color": p.border,
  "app-header-background-color": p.background,
  "app-header-text-color": p.foreground,
  "sidebar-background-color": p.background,
  "sidebar-text-color": p.foreground,
  "sidebar-selected-text-color": p.foreground,
  "sidebar-selected-icon-color": p.foreground,
  "state-icon-color": p["muted-foreground"],
  "state-active-color": p.energy,
  "error-color": p.destructive,
  "warning-color": p.warning,
  "success-color": p.success,
  "info-color": p.info,
  "switch-checked-color": p.primary,
  "switch-checked-button-color": p["primary-foreground"],
  "switch-checked-track-color": p.primary,
  "input-fill-color": p.card,
  "mdc-theme-primary": p.primary,
});
const yamlBlock = (o, indent) =>
  Object.entries(o)
    .map(([k, v]) => `${" ".repeat(indent)}${k}: "${v}"`)
    .join("\n");

const yaml = `# GENERATED by packages/tokens/build.mjs from tokens.json — do not edit by hand.
# Install: copy to /config/themes/ (frontend: themes: !include_dir_merge_named themes), then
# Developer tools → Actions → frontend.reload_themes, and pick "shadcn_ui" in your profile.
shadcn_ui:
  font-family: '${t.font}'
  modes:
    light:
${yamlBlock(ha(t.light), 6)}
    dark:
${yamlBlock(ha(t.dark), 6)}
`;

const outputs = [
  [resolve(here, "theme.css"), css],
  [resolve(here, "../../themes/shadcn_ui.yaml"), yaml],
];

let stale = false;
for (const [file, content] of outputs) {
  if (check) {
    if (!existsSync(file) || readFileSync(file, "utf8") !== content) {
      console.error(`stale: ${file} — run \`pnpm theme\``);
      stale = true;
    }
  } else {
    writeFileSync(file, content);
    console.log(`wrote ${file}`);
  }
}
if (stale) process.exit(1);
